<H5> udpate</H5><P>

some functional code:
<c>
use Data::Dump;

sub qre(&;@) {
  my $block = shift;
  my $str = $block->(@_);
  return qr/$str/;
}

sub ored {
   return join '|', map {quotemeta} @_
}

sub oredraw {
   return join '|', @_
}

my @strings = qw/. | %/ ;


dd qre {join '|', map {quotemeta} @strings };

dd qre \&ored, @strings;

dd qre \&oredraw, @strings;

</c>
